const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.HSB, 100);//繧ｫ繝ｩ繝ｼ繝｢繝ｼ繝会ｼ・SB縲・00谿ｵ髫趣ｼ・
p5obj.noStroke();//譫邱壹↑縺・
var a, b; //螟画焚・・=螟門・縺ｮ逶ｴ蠕・｜=蜀・・縺ｮ逶ｴ蠕・ｼ・
for (var i=0; i<500; i=i+50)
{//10蝗樒ｹｰ繧願ｿ斐＠
  for (var j=0; j<500; j=j+50)
  {//10蝗樒ｹｰ繧願ｿ斐＠
    p5obj.fill(p5obj.random(70, 80), 50, 80);//邏ｫ縺｣縺ｽ縺・牡縺ｫ險ｭ螳・
    a=p5obj.random(30, 50);//30縲・0縺ｮ髢薙・荵ｱ謨ｰ繧呈ｱゅａ繧・
    p5obj.ellipse(i+25, j+25, a, a);//螟門・縺ｮ蜀・・謠冗判
    p5obj.fill(p5obj.random(10, 30), 50, 80);//鮟・牡縲憺ｻ・ｷ・
    b=p5obj.random(0, 20);//0縲・0縺ｮ髢薙・荵ｱ謨ｰ繧呈ｱゅａ繧・
    p5obj.ellipse(i+25, j+25, b, b);//蜀・・縺ｮ蜀・・謠冗判
  }
}

  };
};

export default sketch;
