const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.noStroke();
p5obj.background(255);  //閭梧勹繧堤區縺上☆繧・

for (var iX=-40; iX<600; iX+=40)  //逕ｻ髱｢遶ｯ縺ｮ蜃ｦ逅・・縺溘ａ縺ゅ∴縺ｦ縺ｯ縺ｿ蜃ｺ縺・
{
  for (var iY=-40; iY<600; iY+=40)  //逕ｻ髱｢遶ｯ縺ｮ蜃ｦ逅・・縺溘ａ縺ゅ∴縺ｦ縺ｯ縺ｿ蜃ｺ縺・
  {
    p5obj.fill((iX+iY)% 200);
    //逋ｽ縺上↑繧翫☆縺弱↑縺・げ繝ｩ繝・・繧ｷ繝ｧ繝ｳ
    p5obj.square(iX, iY, 20);


    p5obj.beginShape();
    //蜊・ｳ･譬ｼ蟄舌・1蜊倅ｽ榊・繧呈緒縺・
    p5obj.vertex(iX, iY);
    p5obj.vertex(iX, iY-10);
    p5obj.vertex(iX+10, iY);
    p5obj.vertex(iX+20, iY);
    p5obj.vertex(iX+40, iY+20);
    p5obj.vertex(iX+30, iY+20);
    p5obj.vertex(iX+20, iY+10);
    p5obj.vertex(iX+20, iY+20);
    p5obj.vertex(iX+10, iY+20);
    p5obj.vertex(iX+20, iY+30);
    p5obj.vertex(iX+20, iY+40);
    p5obj.vertex(iX, iY+20);
    p5obj.vertex(iX, iY+10);
    p5obj.vertex(iX, iY+10);
    p5obj.vertex(iX-10, iY);
    p5obj.endShape(p5obj.CLOSE);
  }
}

  };
};

export default sketch;
