const sketch = (p5obj:any) => {
/**
振り子のついた鳩時計
秒針の色が徐々に変化し、針が０に到達すると鳩が出てくる
*/

let x: number = 0;

p5obj.setup = () => 
{
  p5obj.createCanvas(500,620);
  p5obj.frameRate(60);
  p5obj.colorMode(p5obj.HSB,360,100,100,100);
  p5obj.noStroke();
}

 
p5obj.draw = () =>  
{  
  //リフレッシュ
  p5obj.fill(121,82,31);
  p5obj.rect(0,0,p5obj.width,p5obj.height);
  
  //時計本体
  p5obj.fill(0,0,100);
  p5obj.rect(100,130,300,300);
  p5obj.triangle(100, 130, 250, 20, 400, 130);
  //窓
  p5obj.fill(121,57,39);
  p5obj.rect(225,110,50,40);
  p5obj.circle(250,110,50);
  
  let h: number = p5obj.hour()%12;
  let m: number = p5obj.minute();
  let s: number = p5obj.second();
  let arcStart: number = p5obj.PI*1.5;
  
 // 時針
 p5obj.fill(236,53,100,90);
  p5obj.arc(250,300,120,120,arcStart,arcStart+p5obj.radians(h*30));
   
  //分針
  p5obj.fill(9,79,100,60);
  p5obj.arc(250,300,160,160,arcStart,arcStart+p5obj.radians(m*6));

  //秒針
  p5obj.fill(44,79* (s / 60),99,50);
  p5obj.arc(250,300,200,200,arcStart,arcStart+p5obj.radians(s*6));
  
    
 if(s<=2)//秒針が0になると鳩が出てくる
 {
   //鳩の体
   p5obj.fill(0,0,100);
   p5obj.circle(250,105,20);
   p5obj.ellipse(250,125,30,40);
   p5obj.ellipse(240,127,18,33);
   p5obj.ellipse(260,127,18,33);
   //鳩のくちばし
   p5obj.fill(44,79,100);
   p5obj.beginShape();
   p5obj.vertex(250,103);
   p5obj.vertex(245,106);
   p5obj.vertex(250,109);
   p5obj.vertex(255,106);
   p5obj.endShape(p5obj.CLOSE);
 }
 
//振り子
x += 3;
console.log(`x: ${x}`);
  if(x>360) 
  {
    x=0;
  }
  
  p5obj.translate( p5obj.width/2, 550 );
  
  p5obj.fill(360,0,100);
  p5obj.circle(200*p5obj.sin(p5obj.radians(x)),0,60);
}

};

export default sketch;
