// baseMainPage.tsx

import React, { FC, useState, useEffect } from 'react';
import { Navigator } from './Navigator';
import ContentFrame from './ContentFrame';
import { useParams, useNavigate } from 'react-router-dom';

export interface BaseMainPageProps
{
  srcDir: string;       // tsxのディレクトリ  
  binFolder: string;    // バイナリのフォルダ名
  layer0Prefix: string; // -xxコンポーネントのプレフィックス
  navigateRoot: string; // URLルート
  sidebarData: any;     // サイドバー全項目
  anchorTag:  string    // アンカー用タグ
  cssClassname: string; // CSS用のクラス名
  title: string;        // ページのタイトル
  showToLessonsButton?: boolean; // 授業一覧へ戻るボタンを表示するか
}

const BaseMainPage: React.FC<BaseMainPageProps> = (props) => {
  const { param } = useParams();
  const [paramCur, setParamCur] = useState<string>("");
  const navigate = useNavigate(); // useNavigateフックを利用
  const [sidebarElem,setSidebarElem] = useState<number[]>([0,0]);

//  const[ showContentFrame, setShowContentFrame ] = useState<boolean>(false);

  // リンクがクリックされたときの処理
  const handleLinkClick = (IA: number, currentLayer: number, itemIndex: number) => {
    
    // URL更新
    let nextParam = "";
    let updatedSidebarElem = [...sidebarElem];
    if( currentLayer === 0 )
    { // レイヤー0の時クリックした．
      nextParam = `${itemIndex}-0`;
    }
    else
    { // レイヤー1の時クリックした．
      nextParam = `${updatedSidebarElem[0]}-${IA}`;
      console.log(`IA: ${IA}`);
    }
    
    setSidebarElem(updatedSidebarElem);
    navigate(`${props.navigateRoot}${nextParam}`);
  };

  // 現在の授業名がクリックされたときの処理
  const handleCurLessonClick = () => {
    // URL更新
    let updatedSidebarElem = [...sidebarElem];
    updatedSidebarElem[1] = 0;  // Practice ID を0に

    const nextParam = `${updatedSidebarElem[0]}-${updatedSidebarElem[1]}`;
    navigate(`${props.navigateRoot}${nextParam}`);
    if( nextParam !== paramCur )
    {
      //setShowContentFrame(false);
    }
  };

  useEffect(() => {

    console.log( `MainPage: param: ${param}` );
    if( param )
    {
      // URL
      const parts = param.split('-'); // 文字列を分割して配列に格納する
      const numbers = parts.map(part => parseInt(part, 10)); // 各部分を数値に変換する
      setSidebarElem( numbers);
      setParamCur(param);
    }
    //setShowContentFrame(true);

    document.title = props.title;
    
  }, [param]);

  return (
    <div className={props.cssClassname}>
      {/* ContentFrame */}
      {<ContentFrame componentPrefix={`${props.srcDir}${props.layer0Prefix}`} compId={sidebarElem[0]} IA={sidebarElem[1]} navigateRoot={props.navigateRoot} binFolder={props.binFolder} anchorTag={props.anchorTag} />}
      {/* Navigator */}
      {<Navigator onLinkClicked={handleLinkClick} onCurLessonClick={handleCurLessonClick} sidebarElem={sidebarElem} sidebarItems={props.sidebarData} showToLessonsButton={props.showToLessonsButton} />}
    </div>
  );
};

export default BaseMainPage;
