              <CodeBlock>{'int iDeg = 0;\n\nvoid setup()\n{\n  size( 100, 200 );\n}\n\nvoid draw()\n{\n  fill( 204, 30 );\n  noStroke();\n  rect( 0, 0, width, height );\n  \n  translate( width/2, height/2 );\n  \n  fill( 255 );\n  stroke( 0 );\n  circle( 0, 90 * sin( radians( iDeg ) ), 20 );\n          \n  iDeg += 4;\n  if( iDeg > 360 )\n  {\n    iDeg = 0;\n  }\n}'}</CodeBlock>
